<script>
(()=>{const dialog=document.getElementById('newJobDialog');document.getElementById('newRepairJob').onclick=()=>dialog.showModal();document.getElementById('closeNewJob').onclick=()=>dialog.close();if({{ Illuminate\Support\Js::from((bool)old('create_job') || request()->boolean('new')) }})dialog.showModal();document.querySelector('.rj-form').addEventListener('submit',event=>{for(const input of event.currentTarget.querySelectorAll('input,select,textarea')){if(!input.checkValidity()){event.preventDefault();const more=input.closest('details');if(more)more.open=true;input.reportValidity();break;}}});document.querySelectorAll('[data-job-url]').forEach(row=>{row.addEventListener('click',event=>{if(!event.target.closest('a,button,input,select'))location.href=row.dataset.jobUrl;});row.addEventListener('keydown',event=>{if((event.key==='Enter'||event.key===' ')&&event.target===row){event.preventDefault();location.href=row.dataset.jobUrl;}});});})();
</script>
<script>
(()=>{
 const $=id=>document.getElementById(id),query=$('rj_vehicle_query'),selected=$('rj_vehicle'),info=$('rj_vehicle_selected'),dialog=$('rjVehicleDialog'),button=$('rj_vehicle_search');
 const url={{ Illuminate\Support\Js::from(route('ccs.vehicles.search')) }};
 const t=value=>window.ccsText?window.ccsText(value):value;
 let version=0;
 const node=(tag,text)=>{const element=document.createElement(tag);element.textContent=text;return element;};
 function choose(vehicle){const changed=selected.value!==String(vehicle.id);if(changed)$('rj_mileage').value='';let option=[...selected.options].find(option=>option.value===String(vehicle.id));if(!option){option=node('option','');option.value=vehicle.id;selected.append(option);}option.textContent=vehicle.registration_number+' · '+vehicle.customer_name+' · '+vehicle.make+' '+vehicle.model;selected.value=String(vehicle.id);info.textContent=option.textContent+' · '+vehicle.customer_code+' · '+(vehicle.phone||'');$('rj_mileage_reference').textContent=vehicle.current_mileage_km===null||vehicle.current_mileage_km===undefined?'':t('Last recorded mileage')+': '+vehicle.current_mileage_km+' km';query.value=vehicle.registration_number;if(dialog.open)dialog.close();}
 async function search(){const value=query.value.trim();if(!value){info.textContent=t('Enter a customer ID, phone, plate or model first.');query.focus();return;}const current=++version;button.disabled=true;info.textContent=t('Searching…');try{const response=await fetch(url+'?'+new URLSearchParams({q:value}),{credentials:'same-origin',cache:'no-store',headers:{Accept:'application/json'}});if(!response.ok)throw Error(t('Unable to search. Please try again.'));const body=await response.json();if(current!==version)return;if(!body.data.length){selected.value='';info.textContent=t('No registered vehicle found.');return;}if(body.auto_select){choose(body.data[0]);return;}$('rjVehicleMatches').replaceChildren();for(const vehicle of body.data){const row=node('div','');row.className='rj-vehicle-match';const details=node('div','');details.append(node('strong',vehicle.registration_number+' · '+vehicle.make+' '+vehicle.model),node('div',vehicle.customer_name),node('small',vehicle.customer_code+' · '+(vehicle.phone||'')+' · '+(vehicle.manufacture_year||'')));const select=node('button',t('Select'));select.type='button';select.addEventListener('click',()=>choose(vehicle));row.append(details,select);$('rjVehicleMatches').append(row);}$('rjVehicleMore').textContent=body.has_more?t('More than 50 matches. Narrow the search.'):body.data.length+' '+t('matching vehicles');info.textContent=t('Choose the correct vehicle from the results.');if(!dialog.open)dialog.showModal();}catch(error){if(current===version)info.textContent=error.message;}finally{if(current===version)button.disabled=false;}}
 button.addEventListener('click',search);query.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();search();}});query.addEventListener('input',()=>{version++;button.disabled=false;selected.value='';info.textContent='';$('rj_mileage_reference').textContent='';$('rj_mileage').value='';});$('rjVehicleClose').addEventListener('click',()=>dialog.close());
 if(selected.value){const option=selected.selectedOptions[0];info.textContent=option.textContent+' · '+option.dataset.customerCode+' · '+(option.dataset.phone||'');query.value=option.dataset.plate;$('rj_mileage_reference').textContent=option.dataset.mileage?t('Last recorded mileage')+': '+option.dataset.mileage+' km':'';}
 document.querySelector('.rj-form').addEventListener('submit',event=>{if(!selected.value){event.preventDefault();event.stopImmediatePropagation();info.textContent=t('Search and select the customer vehicle first.');query.focus();}},true);
})();
</script>
